package com.bank.portfolio;

import java.util.Arrays;
import java.util.logging.*;

public class ExceptSelfDemo {
    private static final Logger log = Logger.getLogger(ExceptSelfDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Daily growth multipliers (scaled integers for the demo)
        int[] growth = {2, 3, 4, 5};

        ProductAnalyzer analyzer = new ProductAnalyzer();
        int[] result = analyzer.productExceptSelf(growth);

        log.info("Computing product of all other days for each day (no division)");
        log.info("Input  -> " + Arrays.toString(growth));
        log.info("Result -> " + Arrays.toString(result));
    }
}

